function checkDose(id, dose, o = {}) {
  const S = SAFE[id]; if (!S) return null;
  const tau = o.tau || null, wt = o.wt || null, crcl = o.crcl || null;
  const per = tau ? 24 / tau : 1, day = dose * per;
  const red = [], amber = [], ok = [], skip = [];
  const fx = x => (Math.round(x * 10) / 10).toLocaleString('en-US');
  if (S.dose) {
    const [lo, hi, max, ext] = S.dose;
    if (ext && dose > ext) red.push(`${fx(dose)} mg per dose is above even the high-dose limit of ${fx(ext)} mg.`);
    else if (dose > max) (ext ? amber : red).push(ext ? `${fx(dose)} mg per dose is above the label maximum (${fx(max)} mg) — only in specialist high-dose regimens (up to ${fx(ext)} mg).` : `${fx(dose)} mg per dose exceeds the maximum single dose of ${fx(max)} mg.`);
    else if (dose > hi) amber.push(`${fx(dose)} mg is above the usual dose (${fx(lo)}–${fx(hi)} mg) but within the maximum ${fx(max)} mg — confirm the indication.`);
    else if (dose < lo) amber.push(`${fx(dose)} mg is below the usual adult dose (${fx(lo)}–${fx(hi)} mg) — confirm (renal adjustment, paediatric or prophylaxis?).`);
    else ok.push(`Dose ${fx(dose)} mg is within the usual range (${fx(lo)}–${fx(hi)} mg).`);
  }
  if (S.day && tau) {
    const [hi, max, ext] = S.day;
    if (ext && day > ext) red.push(`Daily total ${fx(day)} mg/day is above the high-dose limit of ${fx(ext)} mg/day.`);
    else if (max && day > max) (ext ? amber : red).push(ext ? `Daily total ${fx(day)} mg/day exceeds the label maximum (${fx(max)} mg/day) — specialist regimen only.` : `Daily total ${fx(day)} mg/day EXCEEDS the maximum ${fx(max)} mg/day.`);
    else if (day > hi) amber.push(`Daily total ${fx(day)} mg/day is above the usual ${fx(hi)} mg/day — confirm the indication.`);
    else ok.push(`Daily total ${fx(day)} mg/day is within the maximum.`);
  } else if (S.day && !tau) skip.push('Choose the frequency to check the daily total.');
  if (S.kg || S.kgDay) {
    if (!wt) skip.push('Enter the weight to check the mg/kg dose.');
    else {
      const k = dose / wt, kd = k * per;
      if (S.kg) {
        const [lo, hi, max, ext] = S.kg;
        if (ext && k > ext) red.push(`${fx(k)} mg/kg per dose is above even the high-dose limit of ${ext} mg/kg.`);
        else if (k > max) (ext ? amber : red).push(ext ? `${fx(k)} mg/kg per dose is above the label maximum (${max} mg/kg) — specialist high-dose regimen only (up to ${ext} mg/kg).` : `${fx(k)} mg/kg per dose EXCEEDS the maximum ${max} mg/kg.`);
        else if (k > hi) amber.push(`${fx(k)} mg/kg is above the usual ${lo}–${hi} mg/kg but within the maximum ${max} mg/kg.`);
        else if (k < lo) amber.push(`${fx(k)} mg/kg is below the usual ${lo}–${hi} mg/kg — confirm.`);
        else ok.push(`${fx(k)} mg/kg per dose is within the usual ${lo}–${hi} mg/kg.`);
      }
      if (S.kgDay && tau) {
        const [max, ext] = S.kgDay;
        if (ext && ext > max && kd > ext) red.push(`${fx(kd)} mg/kg/day is above the high-dose limit of ${ext} mg/kg/day.`);
        else if (kd > max + 1e-9) ((ext && ext > max) ? amber : red).push((ext && ext > max) ? `${fx(kd)} mg/kg/day exceeds the label maximum (${max} mg/kg/day) — specialist regimen with monitoring only.` : `${fx(kd)} mg/kg/day EXCEEDS the maximum ${max} mg/kg/day.`);
        else ok.push(`${fx(kd)} mg/kg/day is within the maximum ${max} mg/kg/day.`);
      }
    }
  }
  if (S.renal) {
    if (crcl == null) skip.push(`Enter CrCl: dose reduction is required below ${S.renal} mL/min.`);
    else if (crcl < S.renal) amber.push(`CrCl ${fx(crcl)} mL/min — this medicine needs renal dose adjustment below ${S.renal} mL/min. Check that the dose or interval has been reduced.`);
    else ok.push(`CrCl ${fx(crcl)} mL/min — no renal adjustment needed.`);
  }
  if (S.tdm) amber.length || red.length ? 0 : ok.push('Therapeutic drug monitoring (levels) required.');
  const level = red.length ? 'red' : amber.length ? 'amber' : 'green';
  return { level, red, amber, ok, skip, src: S.src, alert: S.alert || null, day: tau ? day : null };
}


