    'ampho':'amphotericin-b-liposomal','amphotericin':'amphotericin-b-liposomal','amika':'amikacin','teic':'teicoplanin-200-mg','tige':'tigecycline-50-mg','tigecyclin':'tigecycline-50-mg',
    'colistin':'colistin-methanesulfonate-colistimethate-2-million-units','cro':'ceftriaxone-1000-mg-2000-mg','ceftriax':'ceftriaxone-1000-mg-2000-mg','cefaz':'cefazolin-1000-mg',
    'ceftaz avi':'ceftazidime-avibactam-2-5-g-2000-mg-500-mg','ceftolozane tazobactam':'zerbaxa-ceftolozane-tazobactam-1-5-g','unasyn':'ampicillin-sulbactam-1-5-gm',
    'amp sulbactam':'ampicillin-sulbactam-1-5-gm','potassium chloride':'potassium-chloride-2-mmol-ml-10-ml','mag':'magnesium-sulfate-10-50','magnesium':'magnesium-sulfate-10-50',
    'calcium':'calcium-gluconate-100-mg-ml','bicarbonate':'sodium-bicarbonate-8-4-1mmol-ml-50-ml','iron':'iron-saccharate-20-mg-ml-5-ml','ivig':'ivig-10-percent-10-g-100-ml',
